  @case 'search: a deferral moves the charge rather than dodging it'  [pure]  @ 1143-1165
  @case 'search: a held sonority is charged in its own onset's slot'  [pure]  @ 1169-1181
  @case 'search: the road that pays as it goes is the road the walk keeps'  [pure]  @ 1185-1198
  @case 'search: a wait resolving to what its sonority offered is no second road'  [pure]  @ 1202-1215
  @case 'search: a wait that lands tied to nothing refuses the road that took it'  [pure]  @ 1219-1242
